import{_ as i,o as n,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Agency member credit","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subscription-billing/member-credit/spec.md","filePath":"feature/subscription-billing/member-credit/spec.md"}'),t={name:"feature/subscription-billing/member-credit/spec.md"};function o(s,e,l,c,d,u){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="agency-member-credit" tabindex="-1">Agency member credit <a class="header-anchor" href="#agency-member-credit" aria-label="Permalink to &quot;Agency member credit&quot;">​</a></h1><h2 id="unified-caption-video-integration-—-2026-10-21" tabindex="-1">Unified Caption/Video integration — 2026-10-21 <a class="header-anchor" href="#unified-caption-video-integration-—-2026-10-21" aria-label="Permalink to &quot;Unified Caption/Video integration — 2026-10-21&quot;">​</a></h2><p><a href="./../../credit-unification/spec.html">Credit unification</a> supersedes the historical notes about unchanged legacy consumers below. All new Caption/Video fees, workspace balance and Dashboard reads use DA-974; legacy rows are retained without conversion. Refine/Adapt share CAPTION_VARIANTS. Workspace billable POSTs require Idempotency-Key. New additive SQL links Video history to reservations and widens Caption history fees; no extra accounting tables or price seed. See <a href="./../../credit-unification/rollout.html">rollout</a> for pending application-DB migration and live test prerequisites.</p><h2 id="da-974-commit-boundary" tabindex="-1">DA-974 commit boundary <a class="header-anchor" href="#da-974-commit-boundary" aria-label="Permalink to &quot;DA-974 commit boundary&quot;">​</a></h2><p>This feature commits Agency/member accounting, configuration/reporting and fixed operation-price AI integration. Actual token/hardware-cost metering on self-hosted Vast is deferred by the product owner. Payment demo UI, unrelated Campaign/Task UI and Task migration changes are not part of the Credit commit. Local verification sources/logs/screenshots/build products remain ignored; test.md/manual-test.md are required feature documentation, not executable test suites.</p><h2 id="ai-integration-slice-—-2026-10-20" tabindex="-1">AI integration slice — 2026-10-20 <a class="header-anchor" href="#ai-integration-slice-—-2026-10-20" aria-label="Permalink to &quot;AI integration slice — 2026-10-20&quot;">​</a></h2><p>Dev seed confirmed: Demo Agency <code>23dc3d67-4c4b-4a0a-8b91-da5968dbbbb9</code>, dev Owner <code>user177@hotmail.com</code>, 100 credits under DEV_SEED, nonexpiring and separate from purchases. No subscription exists for this Owner; local seed establishes a monthly usage anchor only when absent. PLAN then PURCHASED then DEV_SEED allocation order. Additive <code>developmentAvailable</code> in balance response; omitted by older servers means zero. No public DEV_SEED grant API; only the guarded local seed script.</p><p>Owner access confirmed: allow Owner into Editor and AI Studio routes to consume AI; retain all existing server-side Task/edit/submit/publish authorization. Do not grant Client access or change other route permissions.</p><ul><li>Seven Business AI generation routes enforce Credit before dispatch. <code>X-AI-Workspace-Id</code> is explicit (separate from Gateway&#39;s JWT-derived X-Workspace-Id); Agency is resolved server-side. Permissions are revalidated and supplied tenant IDs overwritten. <code>Idempotency-Key</code> identifies a deliberate generation; technical retry retains it.</li><li>Each adapter produces one image/video or one text request (including caption variants). A durable claim prevents repeat provider calls across processes/restarts. Retain responses for same-key replay, not image input payloads. Changed payload/key reuse conflicts.</li><li>Usable synchronous output settles one unit; explicit failed/empty output settles zero. Validation/rejection HTTP 400/413/422/429 releases the hold. Network timeout, ambiguous server failure or crash stays held, without automatic redispatch/refund. UI explains pending reconciliation.</li><li>Video job IDs bind to reservations and originating users. Only that authorized user can poll. A bounded worker also polls pending jobs after Editor closes. COMPLETED requires a video URL; FAILED releases. Missing/old jobs do not automatically refund.</li><li>Web uses shared AI service for context/key, translates Credit errors and invalidates reports after calls. No public reserve/settle/grant, publish or content-writing changes. Parallel vi/en <code>credit.ai.*</code> text, existing theme retained.</li><li>AI upstream generation endpoints require the internal service key; close the existing unguarded hashtag route to prevent bypassing Business accounting. Upstream must remain internal-only in deployment.</li><li>Dev funding is explicitly authorized local seed, not fabricated payment. Confirm exact Agency first: dev Owner owns several. Missing prices stay blocked until Admin configures them.</li></ul><p>&gt; Database revision: <a href="./compact-schema.html">compact-schema.md</a> supersedes the earlier eight-table layout below. SQL/init and Business stores now use four independent Credit tables, Agency/member columns and derived usage. Public API contracts are unchanged. Do not deploy a previous eight-table build against this baseline; AI/payment hook integration remains pending.</p><h2 id="status-and-scope" tabindex="-1">Status and scope <a class="header-anchor" href="#status-and-scope" aria-label="Permalink to &quot;Status and scope&quot;">​</a></h2><h3 id="web-reporting-slice-—-2026-10-20" tabindex="-1">Web reporting slice — 2026-10-20 <a class="header-anchor" href="#web-reporting-slice-—-2026-10-20" aria-label="Permalink to &quot;Web reporting slice — 2026-10-20&quot;">​</a></h3><ul><li>Extend existing <code>/agency/:id/credit</code>, not a new billing module. Resolve Agency ownership from the URL Agency&#39;s server response and current user ID; never infer Owner from the selected Workspace. Owner sees balance/default/member controls, Manager/Creator see own limit and usage only; Client is excluded. Backend authorization remains authoritative.</li><li>Owner balance shows Plan available, purchased available, total available (sum, held already excluded) and held separately. No claim of aggregate Agency spending: that endpoint does not exist. Load member details only on selection; no per-member request fan-out. Owner can also view own tracked usage, with no personal ceiling.</li><li>Usage uses the server subscription period, used, held and operation breakdown. Personal remaining is max(0, limit-used-held), not guaranteed shared funds. NULL Owner limit means no personal ceiling, never unlimited Agency money. Missing account/cycle is a prerequisite state, distinct from genuine zero usage and missing-schema errors. No history date filter or charts fabricated from current-period APIs.</li><li>Reuse Admin price editor; show per-request/per-image/per-video billing units. Members may read current catalog; no price edits outside Admin. Missing, disabled and explicit free price are distinct. No buy-credit button or direct reserve/settle/grant calls; AI/Payment integration remains pending and is disclosed compactly.</li><li>Inline configuration save and Enter submission; preserve draft on failure, require reload after 409 and show loading/empty/403/503/account-not-ready states without mock data. Invalidate inherited member-limit/usage queries after default changes and matching member usage after override changes. Cached data must be scoped by authenticated user and Agency; do not show one user&#39;s/member&#39;s result under another.</li><li>Text keys in parallel <code>src/i18n/locales/{vi,en}/credit.json</code>: balance.<em>, usage.</em>, catalog.<em>, unit.</em>, unitName.<em>, sourceLabel.</em>, integration.*, refresh, member.search/noResults/selected, errors.account/notFound and existing forms/source/errors keys. BrandHub primitives/tokens retained; keyboard labels/focus, light/dark and 375/768/1440 widths required.</li></ul><p>Confirmed by product owner on 2026-10-19. Implements FR 3.9.5/3.9.7 with Manager support and an Admin operation price catalog. Payment implementation is owned by the payment integration; no PayOS changes here.</p><h2 id="confirmed-rules" tabindex="-1">Confirmed rules <a class="header-anchor" href="#confirmed-rules" aria-label="Permalink to &quot;Confirmed rules&quot;">​</a></h2><h3 id="confirmation-—-2026-10-20-supersedes-pending-default-units-below" tabindex="-1">Confirmation — 2026-10-20 (supersedes pending default/units below) <a class="header-anchor" href="#confirmation-—-2026-10-20-supersedes-pending-default-units-below" aria-label="Permalink to &quot;Confirmation — 2026-10-20 (supersedes pending default/units below)&quot;">​</a></h3><ul><li>Global fallback is 10 credits per member per period. Agency default overrides it, then member override. Owner has no personal limit. The example 3 credits/image is not an authorized price and is not seeded.</li><li>Content/caption/hashtag costs one configured price per successful request; image/video cost per successful output. Partial success charges successful outputs only.</li><li>After subscription expiration, purchased credit remains spendable and member usage continues resetting monthly from the last authoritative subscription anchor. Calendar arithmetic is anchored, not successive 30-day durations; old-period reservations settle against their original period.</li><li>Only verified entitlement/payment integration may supply grants. No public balance minting route, no inference of payment from ACTIVE subscription alone. Subscription/Payment implementation remains another member&#39;s responsibility.</li></ul><h3 id="accounting-scope" tabindex="-1">Accounting scope <a class="header-anchor" href="#accounting-scope" aria-label="Permalink to &quot;Accounting scope&quot;">​</a></h3><p>PostgreSQL stores Agency account anchor, period-scoped Plan/nonexpiring purchased grants, member usage by period, durable reservations and grant allocations. Agency account row serializes grants/reservations/settlements; no transaction remains open across AI network calls. Reserve includes both active holds and settled use against the personal ceiling. Price version and allocation are retained with each reservation. Repeated request key must match operation, Workspace, units and server-computed payload hash. Settlement/release is idempotent, including zero-success and old-period completion. An unknown network outcome stays reserved for reconciliation, never blindly refunded on a timer.</p><ul><li>Agency credit is shared; member limits are independent spending ceilings, not reserved allocations. Sum of ceilings may exceed the shared balance.</li><li>Owner, Manager and Creator may consume credit. Client may not. Owner consumption is tracked but has no personal ceiling; the shared balance still applies.</li><li>Owner configures the Agency default ceiling and member-specific overrides. New members inherit the Agency default, or the confirmed system fallback of 10, without manual approval. A ceiling is not a balance grant.</li><li>Member usage resets with the subscription period; configured ceilings persist. Plan credit does not roll over; purchased credit persists and Plan credit is consumed first.</li><li>Admin configures a non-negative integer price per supported operation. Zero is an explicit free price; missing/disabled pricing is not silently free. Each change produces an immutable version. A future reservation captures that version, independent of later changes.</li><li>Reserve before generation; settle successful units; release unused reservations only after authoritative failure/cancellation. Technical retries are idempotent; explicit regeneration is a new operation; reuse does not charge.</li><li>Subscription/payment activation and top-up must not be inferred from a browser return URL.</li></ul><h2 id="integration-boundary-and-remaining-input" tabindex="-1">Integration boundary and remaining input <a class="header-anchor" href="#integration-boundary-and-remaining-input" aria-label="Permalink to &quot;Integration boundary and remaining input&quot;">​</a></h2><ol><li>Product owner confirmed focus on one Agency; Subscription is owned by another member. Do not duplicate the Owner subscription quota across Agencies. Provisioning requires their explicit Agency grant contract.</li><li>System default confirmed as 10. The member-limit API now returns SYSTEM_DEFAULT/10 when no override/default exists; policy API still returns null/revision zero for an unconfigured Agency policy so Owner can create one explicitly.</li><li>Purchased balance remains usable after subscription expiration/cancellation (confirmed).</li><li>Concrete operation prices are supplied by Admin, never seeded as assumed business prices. Units are confirmed (successful request/output); each adapter must still validate the actual successful output, not merely HTTP 200.</li></ol><h2 id="first-implementation-slice" tabindex="-1">First implementation slice <a class="header-anchor" href="#first-implementation-slice" aria-label="Permalink to &quot;First implementation slice&quot;">​</a></h2><p>Additive PostgreSQL configuration only: Agency policy, generic member overrides, immutable operation price versions. Owner-only writes use revision checks. Owner can manage current Agency members (including members not assigned a Workspace yet), but cannot set a personal Owner limit. Members can read only their effective ceiling; consumption authorization will additionally validate the actual Workspace role. Legacy creator tables, usage totals, dashboards and AI endpoints are unchanged. Configuration defaults are resolved without granting money; join-time inheritance and period usage come later.</p><h2 id="api-and-errors" tabindex="-1">API and errors <a class="header-anchor" href="#api-and-errors" aria-label="Permalink to &quot;API and errors&quot;">​</a></h2><ul><li>GET/PUT <code>/api/v1/agencies/{agencyId}/credit/policy</code>: Owner only, nullable default and revision; writes require <code>expectedRevision</code>.</li><li>GET <code>/api/v1/agencies/{agencyId}/credit/members/me</code>: Owner or current internal Agency member; own effective limit and override source. Owner has null personal limit.</li><li>GET <code>/api/v1/agencies/{agencyId}/credit/members/{memberId}/limit</code>: Owner only; current member&#39;s effective limit and revision before editing.</li><li>PUT <code>/api/v1/agencies/{agencyId}/credit/members/{memberId}/limit</code>: Owner only, current member, nonnegative limit, <code>expectedRevision</code>.</li><li>GET <code>/api/v1/credit/prices</code>: authenticated users, bounded supported operation catalog only.</li><li>PUT <code>/api/v1/admin/credit/prices/{operation}</code>: Admin only, price, enabled, expected revision. Conflicting revisions return 409; no silent overwrite.</li><li>Explicit errors for unconfigured policy, forbidden access, missing Agency/member, unsupported operation and stale configuration. No public grant/reserve/settle endpoint in this slice.</li></ul><h2 id="ui-acceptance-later-slice" tabindex="-1">UI acceptance (later slice) <a class="header-anchor" href="#ui-acceptance-later-slice" aria-label="Permalink to &quot;UI acceptance (later slice)&quot;">​</a></h2><p>Use existing UI primitives/theme, keyboard accessible inputs, inline numeric validation, read-only Owner unlimited state, separate shared balance and personal ceiling. Add parallel vi/en <code>credit.*</code> keys and verify light/dark at mobile/tablet/desktop. No fabricated balance or fallback mock; no payment buttons until payment contract is ready.</p><h2 id="configuration-ui-slice-—-2026-10-19" tabindex="-1">Configuration UI slice — 2026-10-19 <a class="header-anchor" href="#configuration-ui-slice-—-2026-10-19" aria-label="Permalink to &quot;Configuration UI slice — 2026-10-19&quot;">​</a></h2><ul><li>Owner entry <code>/agency/:id/credit</code>: default limit form, Owner unlimited notice and member selector showing one member&#39;s effective ceiling/source before changing it. Reuse current Agency member list, never issue one credit request per member. Explicit save, preserve inputs on failure, require reloading current data after stale revision before retrying.</li><li>Admin entry <code>/admin/credit-prices</code>: supported operation selector with current price/revision/enabled flag. Missing price is unconfigured, not zero; saving creates a version. Labels call this a configuration, not an active billing system; consumption units await AI adapter confirmation.</li><li>Scoped React Query keys include logged-in user and Agency/operation. Route access and Sidebar match existing Owner/Admin security; backend remains authoritative. No change to existing Admin panel, Subscription UI, publish, editor, or global theme.</li><li>Text namespace <code>credit</code> in parallel vi/en JSON: title, policy, member, price, operation, source, errors and pending-integration notice. Whole-number nonnegative safe-integer validation. Zero allowed explicitly; blank never silently coerced to zero. Keyboard labels, inline errors/live status, disabled saving, light/dark tokens and mobile stacking.</li></ul><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>This slice: schema and configuration APIs compile and pass isolated checks, init/migration parity, no production data mutation. Whole feature: period provisioning, immutable request pricing, atomic reserve/settle/release, scoped reporting and UI tested end-to-end; not claimed complete by configuration alone.</p>',32)])])}const g=i(t,[["render",o]]);export{p as __pageData,g as default};
